(function(){
'use strict';
const form=document.querySelector('[data-contact-form]');
if(!form)return;
const status=form.querySelector('[data-contact-status]');
const emailBtn=form.querySelector('[data-send-email]');
const waBtn=form.querySelector('[data-send-whatsapp]');
const getData=()=>Object.fromEntries(new FormData(form).entries());
const validate=()=>{
if(!form.reportValidity())return null;
const d=getData();
if(!String(d.message||'').trim()){status.textContent=form.dataset.errorMessage||'Please enter a message.';status.className='status error';return null;}
status.textContent='';status.className='status';return d;
};
emailBtn.addEventListener('click',()=>{
const d=validate();if(!d)return;
const subject=String(d.subject||'Fastoolee contact');
const body=[`Name: ${d.name}`,`Email: ${d.email}`,'',String(d.message)].join('\n');
location.href=`mailto:sitedoctor3@gmail.com?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
});
waBtn.addEventListener('click',()=>{
const d=validate();if(!d)return;
const text=[`Fastoolee — ${d.subject}`,`Name: ${d.name}`,`Email: ${d.email}`,'',String(d.message)].join('\n');
window.open(`https://wa.me/212614501203?text=${encodeURIComponent(text)}`,'_blank','noopener,noreferrer');
});
})();